content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-12-finance-010

=== 用户原始指令 (query.txt) ===
余额会动 点了跳到记账app 日历看还款日 红色提示要爆预算

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "余额会动 点了跳到记账app 日历看还款日 红色提示要爆预算",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.example.accounting",
        "abilityName": "MainAbility",
        "uri": "ledger://home/add"
      }
    }
  ],
  "dataModelSchema": {
    "asset": {
      "primaryIcon": {
        "type": "string",
        "description": "预算预警卡片使用的日历 glyph 素材路径。",
        "sampleValue": "resources/base/media/calendar_fill.svg"
      }
    },
    "data": {
      "finance": {
        "budgetStatus": {
          "type": "string",
          "description": "当前预算风险状态短文案，用于红色提示。",
          "sampleValue": "快爆预算"
        },
        "balanceText": {
          "type": "string",
          "description": "账户余额的动态展示文本。",
          "sampleValue": "1280元"
        },
        "budgetUsed": {
          "type": "number",
          "description": "预算进度条当前值，超过阈值时按上限内可视值展示。",
          "sampleValue": 96
        },
        "budgetLimit": {
          "type": "number",
          "description": "预算进度条总量基准。",
          "sampleValue": 100
        },
        "progressColor": {
          "type": "string",
          "description": "预算接近爆表时的进度条告警色。",
          "sampleValue": "#ffed6f21"
        }
      },
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "还款日历事件的唯一标识符。",
              "sampleValue": "repay-event-001"
            },
            "title": {
              "type": "string",
              "description": "还款日历事件标题。",
              "sampleValue": "信用卡还款"
            },
            "dtStart": {
              "type": "string",
              "description": "下一次还款日期展示文本。",
              "sampleValue": "07/18"
            },
            "dtEnd": {
              "type": "string",
              "description": "还款日历事件结束日期展示文本。",
              "sampleValue": "07/18"
            }
          }
        ]
      }
    },
    "metric": {
      "left": {
        "label": {
          "type": "string",
          "description": "左侧指标标签。",
          "sampleValue": "余额"
        }
      },
      "right": {
        "label": {
          "type": "string",
          "description": "右侧指标标签。",
          "sampleValue": "还款"
        }
      }
    },
    "action": {
      "label": {
        "type": "string",
        "description": "跳转记账 App 的短动作文案。",
        "sampleValue": "去记账"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/calendar_fill.svg",
      "description": "日历实心 glyph，适合表示还款日、账单日或日历提醒；在深色背景上需要浅色底板保证可读。",
      "bindTo": "/asset/primaryIcon"
    }
  ]
}

=== 待评审 DSL (card.dsl.jsonl，共 3 行) ===
{"version":"v0.9","createSurface":{"surfaceId":"surface_card","catalogId":"ohos.a2ui.extended.catalog","width":140,"height":140}}
{"version":"v0.9","updateComponents":{"surfaceId":"surface_card","root":"root","components":[{"id":"root","component":"Column","children":["header_row","budget_bar","metrics_row","action_button"],"itemMargin":4,"styles":{"width":140,"height":140,"padding":12,"borderRadius":18,"clip":true,"justifyContent":"start","alignItems":"center","backgroundColor":"#ff202224"}},{"id":"header_row","component":"Row","children":["app_icon","status_text"],"itemMargin":6,"styles":{"width":116,"height":20,"justifyContent":"start","alignItems":"center"}},{"id":"app_icon","component":"Image","src":"{{ ${/asset/primaryIcon} }}","styles":{"width":18,"height":18,"padding":2,"borderRadius":6,"backgroundColor":"#ffffffff","objectFit":"contain"}},{"id":"status_text","component":"Text","content":"{{ ${/data/finance/budgetStatus} }}","styles":{"width":92,"height":18,"fontSize":14,"fontWeight":600,"fontColor":"#ffed6f21","maxLines":1,"textOverflow":"none","textAlign":"start"}},{"id":"budget_bar","component":"Row","children":["budget_progress"],"styles":{"width":116,"height":22,"justifyContent":"start","alignItems":"center"}},{"id":"budget_progress","component":"Progress","value":"{{ ${/data/finance/budgetUsed} }}","total":"{{ ${/data/finance/budgetLimit} }}","styles":{"type":"linear","width":116,"height":14,"borderRadius":8,"color":"{{ ${/data/finance/progressColor} }}","backgroundColor":"#19ffffff"}},{"id":"metrics_row","component":"Row","children":["balance_metric","repay_metric"],"itemMargin":8,"styles":{"width":116,"height":36,"justifyContent":"spaceBetween","alignItems":"center"}},{"id":"balance_metric","component":"Column","children":["balance_label","balance_value"],"itemMargin":2,"styles":{"width":54,"height":36,"justifyContent":"center","alignItems":"center"}},{"id":"balance_label","component":"Text","content":"{{ ${/metric/left/label} }}","styles":{"width":54,"height":12,"fontSize":10,"fontWeight":500,"fontColor":"#99ffffff","maxLines":1,"textOverflow":"none","textAlign":"center"}},{"id":"balance_value","component":"Text","content":"{{ ${/data/finance/balanceText} }}","styles":{"width":54,"height":18,"fontSize":14,"fontWeight":700,"fontColor":"#ffffffff","maxLines":1,"textOverflow":"none","textAlign":"center"}},{"id":"repay_metric","component":"Column","children":["repay_label","repay_value"],"itemMargin":2,"styles":{"width":54,"height":36,"justifyContent":"center","alignItems":"center"}},{"id":"repay_label","component":"Text","content":"{{ ${/metric/right/label} }}","styles":{"width":54,"height":12,"fontSize":10,"fontWeight":500,"fontColor":"#99ffffff","maxLines":1,"textOverflow":"none","textAlign":"center"}},{"id":"repay_value","component":"Text","content":"{{ ${/data/calendar/items/0/dtStart} }}","styles":{"width":54,"height":18,"fontSize":16,"fontWeight":700,"fontColor":"#ffffffff","maxLines":1,"textOverflow":"none","textAlign":"center"}},{"id":"action_button","component":"Button","label":"{{ ${/action/label} }}","onClick":[{"call":"clickToDeeplink","args":{"bundleName":"com.example.accounting","abilityName":"MainAbility","uri":"ledger://home/add"}}],"styles":{"width":116,"height":26,"fontSize":12,"fontWeight":600,"fontColor":"#ffffffff","backgroundColor":"#19ffffff","borderRadius":13}}]}}
